SELECT 
FROM jsh_logistics_tracking
WHERE tracking_number = #{trackingNumber}
  AND tenant_id = #{tenantId}
  AND delete_flag = '0'

SELECT 
FROM jsh_logistics_tracking
WHERE work_order_id = #{workOrderId}
  AND tenant_id = #{tenantId}
  AND delete_flag = '0'
ORDER BY create_time DESC

SELECT 
FROM jsh_logistics_tracking
WHERE task_id = #{taskId}
  AND tenant_id = #{tenantId}
  AND delete_flag = '0'
ORDER BY create_time DESC

SELECT 
FROM jsh_logistics_tracking
WHERE status = #{status}
  AND tenant_id = #{tenantId}
  AND delete_flag = '0'
ORDER BY create_time DESC

